{
  "schemaVersion": "0.2",
  "slug": "result",
  "name": "Result",
  "family": "E",
  "status": "experimental",
  "purpose": "Presents the outcome of a process with status icon, title, description, and actions.",
  "scenarios": [
    "Show a payment success page",
    "Display a 404 empty result",
    "Present a failed import summary"
  ],
  "props": {
    "status": {
      "type": "enum",
      "required": false,
      "description": "Outcome tone.",
      "values": [
        "success",
        "error",
        "info",
        "warning"
      ],
      "default": "info"
    },
    "title": {
      "type": "string",
      "required": true,
      "description": "Result headline."
    },
    "description": {
      "type": "string",
      "required": false,
      "description": "Supporting explanation."
    },
    "children": {
      "type": "node",
      "required": false,
      "description": "Action area below the description."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "status",
      "values": [
        "success",
        "error",
        "info",
        "warning"
      ],
      "default": "info",
      "description": "Outcome tone."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Result panel rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "dialog"
    ],
    "allowedChildren": [
      "button",
      "link",
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a result for inline field errors; use InlineAlert.",
    "Do not leave the user without a next action on error results."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Actions follow the description in tab order.",
    "labeling": "Status icon has a text equivalent derived from status.",
    "wcag": [
      "1.1.1",
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Centered single column at all breakpoints.",
    "breakpoints": {
      "compact": "Full width, stacked.",
      "medium": "Centered measure.",
      "large": "Centered measure."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "result",
    "states": [
      "default",
      "success",
      "error",
      "info",
      "warning"
    ],
    "intents": [
      "notify-status"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface ResultProps {
  status?: 'success' | 'error' | 'info' | 'warning'
  title: string
  description?: string
  children?: ReactNode
  className?: string
}

const STATUS_GLYPH = { success: '✓', error: '✕', info: 'ℹ', warning: '⚠' } as const

export function Result({ status = 'info', title, description, children, className }: ResultProps) {
  const classes = ['cu-result', 'cu-result--' + status, className].filter(Boolean).join(' ')
  return (
    <div className={classes} role="status" data-ai-role="result" data-ai-intent="notify-status" data-ai-state={status}>
      <span className="cu-result__icon" aria-hidden="true">
        {STATUS_GLYPH[status]}
      </span>
      <p className="cu-result__title">{title}</p>
      {description ? <p className="cu-result__description">{description}</p> : null}
      {children ? <div className="cu-result__actions">{children}</div> : null}
    </div>
  )
}

.cu-result {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--cu-space-2);
  padding-block: calc(var(--cu-space-3) * 2);
  padding-inline: var(--cu-space-3);
  text-align: center;
  color: var(--cu-color-fg-default);
}

.cu-result__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: calc(var(--cu-space-3) * 4);
  block-size: calc(var(--cu-space-3) * 4);
  border-radius: 50%;
  font-size: 1.5em;
  background: color-mix(in srgb, var(--cu-color-palette-brand) 12%, var(--cu-color-background-default));
}

.cu-result--error .cu-result__icon {
  background: color-mix(in srgb, red 14%, var(--cu-color-background-default));
}

.cu-result--success .cu-result__icon {
  background: color-mix(in srgb, green 14%, var(--cu-color-background-default));
}

.cu-result--warning .cu-result__icon {
  background: color-mix(in srgb, orange 16%, var(--cu-color-background-default));
}

.cu-result__title {
  margin: 0;
  font-size: 1.25em;
  font-weight: 600;
}

.cu-result__description {
  margin: 0;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-result__actions {
  margin-block-start: var(--cu-space-2);
  display: flex;
  gap: var(--cu-space-2);
}
